// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PlatformAppConnection) predicate.PlatformAppConnection {
	return predicate.PlatformAppConnection(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PlatformAppConnection) predicate.PlatformAppConnection {
	return predicate.PlatformAppConnection(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PlatformAppConnection) predicate.PlatformAppConnection {
	return predicate.PlatformAppConnection(sql.NotPredicates(p))
}





